-- Ground effects: the effect ids of groundfx_data.lua (generated by client/tools/sprites/gen_ground_fx.py from
-- ground_fx.csv) are drawn under the creatures (base patch 0055, g_map.setGroundEffect): rune circles, seals, novas,
-- shockwave rings, rifts and the effects that would cover a creature for long. A client without the patch skips this
-- and draws them as before.
GroundFx = {}

-- registers (on = true) or clears (on = false) every id on map; false when the map has no ground effect API
function GroundFx.apply(map, ids, on)
  if type(map) ~= 'table' and type(map) ~= 'userdata' then return false end
  if type(map.setGroundEffect) ~= 'function' then return false end
  for _, id in ipairs(ids or {}) do
    pcall(map.setGroundEffect, id, on and true or false)
  end
  return true
end

function GroundFx.ids()
  return (GroundFxData and GroundFxData.ids) or {}
end

function GroundFx.isGround(id)
  local names = GroundFxData and GroundFxData.names
  return names ~= nil and names[id] ~= nil
end

function init()
  GroundFx.apply(g_map, GroundFx.ids(), true)
end

function terminate()
  GroundFx.apply(g_map, GroundFx.ids(), false)
end
